body { margin: 0; padding: 24px; font-family: sans-serif; background: #edf5f3; color: #143b35; }
.card { width: 100%; max-width: 600px; margin-inline: auto; padding: 24px; border: 1px solid #9cbcb5; border-radius: 12px; background: white; }
label, input, button { display: block; margin-block: 12px; }
